import{Router}from'express';import crypto from'node:crypto';import QRCode from'qrcode';import{db}from'../config/firebase.js';import{env}from'../config/env.js';import{requireAuth,allow,isInstituteOwner}from'../middleware/auth.js';import{can,moduleForCollection,assertScope,normalizeTeacherPermissions,inTeacherScope}from'../services/teacherPermissions.js';import{validateStudentAcademicRelationships}from'../services/academicRules.js';import{examStore}from'./examinations.js';
const r=Router(),collections=new Set(['students','teachers','teacherJoinRequests','teacherInvites','staff','admissions','academicYears','departments','courses','semesters','subjects','classes','sections','batches','questionBanks','assignments','assignmentSubmissions','exams','examAttempts','results','marksheets','auditLogs','settings']);
r.use(requireAuth);
const readAccess=(req,res,next)=>{const c=req.params.collection;if(isInstituteOwner(req.user))return next();const action=['examAttempts','assignmentSubmissions'].includes(c)?'review':'view';return can(req.user,moduleForCollection(c),action)?next():res.status(403).json({message:'You do not have permission to view this resource.'});};
const writeAccess=(req,res,next)=>{const c=req.params.collection;if(isInstituteOwner(req.user))return next();const action=req.method==='POST'?'create':req.method==='PATCH'?(req.body?.status==='archived'?'archive':'edit'):'manage';return can(req.user,moduleForCollection(c),action)?next():res.status(403).json({message:'You do not have permission to change this resource.'});};
const lookupKey=value=>encodeURIComponent(String(value||'').trim().toLowerCase());
const normalizeStudentMobile=value=>{const v=String(value||'').replace(/[\s()-]/g,'');if(/^[6-9]\d{9}$/.test(v))return `+91${v}`;if(/^\+?[1-9]\d{9,14}$/.test(v))return v.startsWith('+')?v:`+${v}`;return null;};
async function matchesStudentTarget(iid,target,student){if(!student)return false;for(const key of ['academicYearId','departmentId','courseId','semesterId','classId','sectionId','batchId'])if(target?.[key]&&String(target[key])!==String(student[key]||''))return false;if(target?.subjectId){if(student.subjectId&&String(target.subjectId)!==String(student.subjectId))return false;if(!student.subjectId){const subject=await db.get(`institutes/${iid}/subjects/${target.subjectId}`);if(!subject)return false;if(subject.courseId&&String(subject.courseId)!==String(student.courseId||''))return false;if(subject.departmentId&&student.departmentId&&String(subject.departmentId)!==String(student.departmentId))return false;if(subject.semesterId&&student.semesterId&&String(subject.semesterId)!==String(student.semesterId))return false;}}return true;}

const academicEntities=new Set(['academicYears','courses','departments','semesters','subjects','classes','sections','batches']);
const academicUsedBy={
 academicYears:[['classes','academicYearId'],['batches','academicYearId'],['students','academicYearId'],['exams','academicYearId']],
 courses:[['semesters','courseId'],['subjects','courseId'],['exams','courseId'],['students','courseId'],['classes','courseId'],['batches','courseId']],
 departments:[['subjects','departmentId'],['exams','departmentId'],['students','departmentId'],['courses','departmentId'],['classes','departmentId'],['batches','departmentId']],
 semesters:[['subjects','semesterId'],['exams','semesterId'],['students','semesterId']],
 subjects:[['questionBanks','subjectId'],['exams','subjectId'],['classes','classId']],
 classes:[['batches','classId'],['sections','classId'],['students','classId']],
 sections:[['students','sectionId']],
 batches:[['students','batchId']]
};
const academicRefs={courses:{departmentId:'departments'},semesters:{courseId:'courses'},subjects:{courseId:'courses',departmentId:'departments',semesterId:'semesters',classId:'classes'},classes:{departmentId:'departments',courseId:'courses',academicYearId:'academicYears'},sections:{classId:'classes'},batches:{departmentId:'departments',courseId:'courses',classId:'classes',academicYearId:'academicYears'}};

const academicModuleKeys=['academicYears','departments','courses','semesters','classes','sections','batches','subjects'];
const academicPresets={
 school:{academicYears:true,departments:true,courses:true,semesters:false,classes:true,sections:true,batches:false,subjects:true},
 college:{academicYears:true,departments:true,courses:true,semesters:true,classes:true,sections:true,batches:false,subjects:true},
 university:{academicYears:true,departments:true,courses:true,semesters:true,classes:true,sections:true,batches:false,subjects:true},
 coaching:{academicYears:true,departments:true,courses:true,semesters:false,classes:true,sections:true,batches:true,subjects:true},
 training:{academicYears:true,departments:true,courses:true,semesters:false,classes:true,sections:true,batches:true,subjects:true},
 custom:{academicYears:true,departments:true,courses:true,semesters:true,classes:true,sections:true,batches:true,subjects:true}
};
const academicLabels={academicYears:'Academic Years',departments:'Departments',courses:'Courses',semesters:'Semesters',classes:'Classes',sections:'Sections',batches:'Batches',subjects:'Subjects'};
function defaultAcademicStructure(type='custom'){
 const rawKey=String(type||'custom').toLowerCase(),key=academicPresets[rawKey]?rawKey:'custom',preset=academicPresets[key];
 const modules={};for(const k of academicModuleKeys)modules[k]={enabled:!!preset[k],label:academicLabels[k]};
 const hierarchy=['academicYears','departments','courses','classes','sections','batches','semesters','subjects'].filter(k=>modules[k].enabled);
 const requiredFields={
  students:[...(modules.departments.enabled?['departmentId']:[]),...(modules.courses.enabled?['courseId']:[]),...(modules.classes.enabled?['classId']:[]),...(modules.sections.enabled?['sectionId']:[])],
  courses:modules.departments.enabled?['departmentId']:[],
  semesters:modules.courses.enabled?['courseId']:[],
  subjects:[...(modules.courses.enabled?['courseId']:[]),...(modules.departments.enabled?['departmentId']:[]),...(modules.semesters.enabled?['semesterId']:[]),...(!modules.courses.enabled&&modules.classes.enabled?['classId']:[])],
  classes:[...(modules.departments.enabled?['departmentId']:[]),...(modules.courses.enabled?['courseId']:[])],
  sections:modules.classes.enabled?['classId']:[],
  batches:[...(modules.departments.enabled?['departmentId']:[]),...(modules.courses.enabled?['courseId']:[]),...(modules.classes.enabled?['classId']:[]),...(modules.academicYears.enabled?['academicYearId']:[])]
 };
 return {version:2,instituteType:key,modules,hierarchy,requiredFields};
}
async function getAcademicStructure(iid){
 const path=`institutes/${iid}/settings/academicStructure`;
 const saved=await db.get(path);
 if(saved?.modules){
  if(Number(saved.version||1)>=2)return saved;
  const fallback=defaultAcademicStructure(saved.instituteType||'custom');
  // Preserve every explicitly saved enabled/disabled choice during migration.
  // Older migration code force-enabled core modules, undoing an owner's settings.
  const modules={...fallback.modules,...saved.modules};
  for(const key of academicModuleKeys){
   modules[key]={...fallback.modules[key],...(saved.modules?.[key]||{})};
   if(typeof saved.modules?.[key]?.enabled!=='boolean') modules[key].enabled=!!fallback.modules[key]?.enabled;
  }
  const oldOrder=Array.isArray(saved.hierarchy)?saved.hierarchy.filter(k=>academicModuleKeys.includes(k)&&modules[k]?.enabled):[];
  const order=oldOrder.filter(k=>!['departments','courses','classes','sections'].includes(k));
  const insertInOrder=(key,after)=>{if(order.includes(key))return;const at=order.indexOf(after);order.splice(at<0?0:at+1,0,key);};
  insertInOrder('departments','academicYears');
  insertInOrder('courses','departments');
  const insertAt=order.findIndex(k=>['batches','semesters','subjects'].includes(k));
  order.splice(insertAt<0?order.length:insertAt,0,'classes','sections');
  const fieldModules={academicYearId:'academicYears',departmentId:'departments',courseId:'courses',semesterId:'semesters',classId:'classes',sectionId:'sections',batchId:'batches'};
  const allowedFields={courses:['departmentId'],semesters:['courseId'],subjects:['courseId','departmentId','semesterId','classId'],classes:['departmentId','courseId','academicYearId'],sections:['classId'],batches:['departmentId','courseId','classId','academicYearId'],students:['academicYearId','departmentId','courseId','semesterId','classId','sectionId','batchId']};
  const requiredFields={};
  for(const [entity,allowed] of Object.entries(allowedFields)){
   const requested=Array.isArray(saved.requiredFields?.[entity])?saved.requiredFields[entity]:(fallback.requiredFields?.[entity]||[]);
   requiredFields[entity]=[...new Set(requested.filter(field=>allowed.includes(field)&&modules[fieldModules[field]]?.enabled))];
  }
  const upgraded={...saved,version:2,modules,hierarchy:order,requiredFields,updatedAt:Date.now(),migration:'academic-structure-v2'};
  await db.set(path,upgraded);
  return upgraded;
 }
 const profile=await db.get(`institutes/${iid}/profile`)||{};
 return defaultAcademicStructure(profile.type||'custom');
}

async function validateAcademic(iid,c,payload,current={}){
 if(!academicEntities.has(c))return;
 const merged={...current,...payload};
 if(payload.status!==undefined&&!['active','inactive'].includes(payload.status)){const e=new Error('Status must be active or inactive.');e.status=400;throw e;}
 if(['courses','departments','subjects'].includes(c)){
  if(!String(merged.name||'').trim()||!String(merged.code||'').trim()){const e=new Error('Name and code are required.');e.status=400;throw e;}
  merged.name=String(merged.name).trim();merged.code=String(merged.code).trim().toUpperCase();payload.name=merged.name;payload.code=merged.code;
  if(merged.code.length>20||!/^[A-Z0-9._-]+$/.test(merged.code)){const e=new Error('Code may contain only letters, numbers, dot, underscore and hyphen (maximum 20 characters).');e.status=400;throw e;}
 }
 if(['classes','sections','batches'].includes(c)&&!String(merged.name||'').trim()){const e=new Error('A name is required.');e.status=400;throw e;}
 if(c==='classes'&&merged.number!==undefined&&merged.number!==''){const n=Number(merged.number);if(!Number.isInteger(n)||n<1||n>20){const e=new Error('Class number must be an integer between 1 and 20.');e.status=400;throw e;}merged.number=n;payload.number=n;}
  
  if(c==='semesters'){
  if(!String(merged.name||'').trim()){merged.name=`Semester ${Number(merged.number)||''}`;payload.name=merged.name;}
  const n=Number(merged.number);
  if(!Number.isInteger(n)||n<1||n>20){const e=new Error('Semester number must be between 1 and 20.');e.status=400;throw e;}
  if(merged.academicYear!==undefined&&merged.academicYear!==''&&!/^\d{4}(-\d{2,4})?$/.test(String(merged.academicYear))){const e=new Error('Enter a valid academic year (e.g. 2026-27).');e.status=400;throw e;}
  merged.number=n;payload.number=n;
 }
 if(c==='courses'&&merged.durationYears!==undefined&&merged.durationYears!==''){const n=Number(merged.durationYears);if(!Number.isFinite(n)||n<.5||n>10){const e=new Error('Course duration must be between 0.5 and 10 years.');e.status=400;throw e;}merged.durationYears=n;payload.durationYears=n;}
 if(c==='subjects'&&merged.credits!==undefined&&merged.credits!==''){const n=Number(merged.credits);if(!Number.isFinite(n)||n<0||n>30){const e=new Error('Credits must be between 0 and 30.');e.status=400;throw e;}merged.credits=n;payload.credits=n;}
 const structure=await getAcademicStructure(iid),required=new Set(structure.requiredFields?.[c]||[]);
 const fieldModules={academicYearId:'academicYears',departmentId:'departments',courseId:'courses',semesterId:'semesters',classId:'classes',sectionId:'sections',batchId:'batches'};
 for(const [field,moduleKey] of Object.entries(fieldModules)){
  const changed=Object.prototype.hasOwnProperty.call(payload,field)&&String(payload[field]||'')!==String(current[field]||'');
  if(!structure.modules?.[moduleKey]?.enabled&&changed&&payload[field]){
   const e=new Error(`The ${moduleKey} module is disabled in this institute's academic structure.`);e.status=400;throw e;
  }
 }
 for(const [field,refCollection] of Object.entries(academicRefs[c]||{})){
  if(!merged[field]){if(required.has(field)){const e=new Error(`Select a valid ${field.replace('Id','')}.`);e.status=400;throw e;}continue;}
  const ref=await db.get(`institutes/${iid}/${refCollection}/${merged[field]}`);
  if(!ref||ref.status==='archived'){const e=new Error(`Selected ${field.replace('Id','')} does not exist or is archived.`);e.status=400;throw e;}
 }
 if(['subjects','classes','batches'].includes(c)&&merged.courseId&&merged.departmentId){const course=await db.get(`institutes/${iid}/courses/${merged.courseId}`);if(course?.departmentId&&course.departmentId!==merged.departmentId){const e=new Error('The selected course does not belong to the selected department.');e.status=400;throw e;}}
  if(c==='batches'){const cls=await db.get(`institutes/${iid}/classes/${merged.classId}`);if(cls&&((cls.courseId&&merged.courseId&&String(cls.courseId)!==String(merged.courseId))||(cls.departmentId&&merged.departmentId&&String(cls.departmentId)!==String(merged.departmentId))||(cls.academicYearId&&merged.academicYearId&&String(cls.academicYearId)!==String(merged.academicYearId)))){const e=new Error('The selected class does not belong to the selected course, department or academic year.');e.status=400;throw e;}}
  if(c==='subjects'){const sem=await db.get(`institutes/${iid}/semesters/${merged.semesterId}`);if(sem&&sem.courseId!==merged.courseId){const e=new Error('The selected semester does not belong to the selected course.');e.status=400;throw e;}const cls=await db.get(`institutes/${iid}/classes/${merged.classId}`);if(cls&&((cls.courseId&&merged.courseId&&String(cls.courseId)!==String(merged.courseId))||(cls.departmentId&&merged.departmentId&&String(cls.departmentId)!==String(merged.departmentId)))){const e=new Error('The selected class does not belong to the selected subject course and department.');e.status=400;throw e;}}
 if(['academicYears','semesters','classes','sections','batches'].includes(c)){
   const rows=await db.get(`institutes/${iid}/${c}`)||{};
   const same=(a,b)=>String(a??'').trim().toLowerCase()===String(b??'').trim().toLowerCase();
   const duplicate=Object.entries(rows).some(([id,row])=>{
    if(id===current.id)return false;
    if(c==='academicYears')return same(row.name,merged.name);
    if(c==='semesters')return Number(row.number)===Number(merged.number)&&same(row.courseId,merged.courseId)&&same(row.academicYear,merged.academicYear);
    if(c==='classes')return same(row.name,merged.name)&&same(row.departmentId,merged.departmentId)&&same(row.courseId,merged.courseId)&&same(row.academicYearId,merged.academicYearId);
    if(c==='sections')return same(row.name,merged.name)&&same(row.classId,merged.classId);
    return same(row.name,merged.name)&&same(row.departmentId,merged.departmentId)&&same(row.courseId,merged.courseId)&&same(row.classId,merged.classId)&&same(row.academicYearId,merged.academicYearId);
   });
   if(duplicate){const e=new Error(c==='sections'?'A section with this name already exists in the selected class.':c==='classes'?'A class with this name already exists in the selected academic group.':c==='batches'?'A batch with this name already exists in the selected academic group.':c==='semesters'?'This semester number already exists for the selected course and academic year.':'This academic year already exists.');e.status=409;throw e;}
  }
  if(['courses','departments','subjects'].includes(c)&&merged.code){
  const rows=await db.get(`institutes/${iid}/${c}`)||{};
  if(Object.entries(rows).some(([id,row])=>id!==current.id&&String(row.code||'').toUpperCase()===merged.code)){const e=new Error(`A ${c.slice(0,-1)} with this code already exists.`);e.status=409;throw e;}
 }
}

async function validateExamQuestionRefs(iid,user,exam){
 const ids=Array.isArray(exam.questionIds)?exam.questionIds:typeof exam.questionIds==='string'?exam.questionIds.split(',').map(x=>x.trim()).filter(Boolean):[];
 const marks=exam.questionMarks&&typeof exam.questionMarks==='object'?exam.questionMarks:{};
 for(const qid of ids){
  const question=await db.get(`institutes/${iid}/questionBanks/${qid}`);
  if(!question){const e=new Error(`Question ${qid} does not exist in this institute.`);e.status=400;throw e;}
  if(user.role==='teacher')assertScope(user,question,'questionBanks');
  if(exam.subjectId&&question.subjectId&&String(question.subjectId)!==String(exam.subjectId)){const e=new Error(`Question ${qid} is outside the examination subject.`);e.status=400;throw e;}
  const assigned=marks[qid]===undefined?Number(question.marks)||1:Number(marks[qid]);
  if(!(assigned>0)||!Number.isFinite(assigned)){const e=new Error(`Enter positive marks for question ${qid}.`);e.status=400;throw e;}
 }
 if((exam.examMode||'online')==='online'&&!ids.length){const e=new Error('Select at least one question for every online subject paper.');e.status=400;throw e;}
}

const studentAcademicRefs={academicYearId:'academicYears',departmentId:'departments',courseId:'courses',semesterId:'semesters',classId:'classes',sectionId:'sections',batchId:'batches'};
const studentAcademicLabels={academicYearId:'academic year',departmentId:'department',courseId:'course',semesterId:'semester',classId:'class',sectionId:'section',batchId:'batch'};
async function validateStudentAcademic(iid,payload,current={}){
 const merged={...current,...payload};
 const structure=await getAcademicStructure(iid);
 const required=new Set(structure.requiredFields?.students||[]);
 const refs={};
 for(const [field,collection] of Object.entries(studentAcademicRefs)){
  const value=merged[field];
  if(!value){
   if(required.has(field)){const e=new Error(`Assign a ${studentAcademicLabels[field]} to this student.`);e.status=400;throw e;}
   continue;
  }
  const unchanged=String(value)===String(current[field]||'');
  if(!structure.modules?.[collection]?.enabled&&!unchanged){const e=new Error(`The ${studentAcademicLabels[field]} module is disabled in this institute's academic structure.`);e.status=400;throw e;}
  const row=await db.get(`institutes/${iid}/${collection}/${value}`);
  if(!row||['archived','inactive'].includes(row.status)){if(unchanged){refs[field]=row||null;continue;}const e=new Error(`Selected ${studentAcademicLabels[field]} does not exist or is inactive.`);e.status=400;throw e;}
  refs[field]=row;
 }
 validateStudentAcademicRelationships(merged,{
  department:refs.departmentId,course:refs.courseId,semester:refs.semesterId,
  academicYear:refs.academicYearId,classRecord:refs.classId,section:refs.sectionId,batch:refs.batchId
 });
 const department=refs.departmentId,course=refs.courseId,semester=refs.semesterId,cls=refs.classId,section=refs.sectionId,batch=refs.batchId,year=refs.academicYearId;
 const names={
  academicYearName:year?.name||merged.academicYearName||merged.academicYear||'',
  departmentName:department?.name||merged.departmentName||'',
  courseName:course?.name||merged.courseName||'',
  semesterName:semester?.name||merged.semesterName||merged.semester||`Semester ${semester?.number||''}`.trim(),
  className:cls?.name||merged.className||'',
  sectionName:section?.name||merged.sectionName||'',
  batchName:batch?.name||merged.batchName||''
 };
 for(const [key,value] of Object.entries(names))payload[key]=value;
 for(const field of Object.keys(studentAcademicRefs))if(!merged[field])payload[`${field}`]=null;
}

async function claimIndex(path,id){const tx=await db.transaction(path,current=>current||id);return tx.committed&&tx.snapshot.val()===id;}
async function releaseIndex(path,id){await db.transaction(path,current=>current===id?null:current);}
async function claimStudentId(instituteId,recordId){for(let n=0;n<20;n++){const code=`JST-${crypto.randomInt(100000,999999)}`,path=`studentIdLookups/${code}`,tx=await db.transaction(path,current=>current||{instituteId,recordId});if(tx.committed&&tx.snapshot.val()?.recordId===recordId)return code;}throw Object.assign(new Error('Could not generate a unique Student ID. Please retry.'),{status:503});}
function cleanCode(value){return String(value||'GEN').toUpperCase().replace(/[^A-Z0-9]/g,'').slice(0,7)||'GEN';}
async function generateAcademicCode(iid,collection,payload){if(!['departments','courses','subjects','batches','sections'].includes(collection))return null;let segment='GEN';if(collection==='departments')segment=cleanCode(payload.code||payload.name);else if(collection==='courses'){const d=payload.departmentId?await db.get(`institutes/${iid}/departments/${payload.departmentId}`):null;segment=cleanCode(d?.code||d?.name||payload.code||payload.name);}else if(collection==='subjects'){const c=payload.courseId?await db.get(`institutes/${iid}/courses/${payload.courseId}`):null;const d=payload.departmentId?await db.get(`institutes/${iid}/departments/${payload.departmentId}`):null;segment=cleanCode(d?.code||c?.code||c?.name||'SUB');}else if(collection==='batches')segment='BATCH';else if(collection==='sections')segment='SEC';const prefix=`JUP-${segment}-${new Date().getFullYear()}`;const rows=await db.get(`institutes/${iid}/${collection}`)||{};for(let n=0;n<30;n++){const letters=String.fromCharCode(65+crypto.randomInt(0,26),65+crypto.randomInt(0,26));const suffix=`${letters}${crypto.randomInt(10,99)}`;const code=`${prefix}${suffix}`;if(code.length>20)throw Object.assign(new Error('Generated academic code exceeds the 20-character limit.'),{status:500});if(!Object.values(rows).some(row=>row.code===code))return code;}throw Object.assign(new Error('Could not generate a unique academic code. Please retry.'),{status:503});}

r.get('/dashboard',async(req,res,next)=>{try{if(!['institute_owner','institute_admin','teacher'].includes(req.user.role))return res.status(403).json({message:'Institute workspace access required.'});const iid=req.user.instituteId;if(!iid)return res.json({institute:null,stats:{},recentAdmissions:[],recentExams:[],recentTeacherRequests:[],recentActivities:[]});await examStore.ensureMigrated(iid);const names=['profile','students','teachers','staff','admissions','departments','courses','subjects','classes','sections','batches','exams','examinations','results','teacherJoinRequests','academicYears'];const [values,auditSnapshot]=await Promise.all([Promise.all(names.map(k=>db.get(`institutes/${iid}/${k}`))),can(req.user,'auditLogs','view')?db.ref(`institutes/${iid}/auditLogs`).orderByKey().limitToLast(40).get():Promise.resolve(null)]);const data=Object.fromEntries(names.map((k,i)=>[k,values[i]]));data.auditLogs=auditSnapshot?.exists()?auditSnapshot.val():null;const owner=isInstituteOwner(req.user);const scoped=c=>Object.entries(data[c]||{}).map(([id,v])=>({id,...v})).filter(x=>x.status!=='archived'&&x.status!=='rejected').filter(x=>owner||inTeacherScope(req.user,x,c));const stats={};for(const c of ['students','teachers','staff','admissions','departments','courses','subjects','classes','sections','batches','exams','results','academicYears']){const mod=moduleForCollection(c);stats[c]=owner?scoped(c).length:(can(req.user,mod,'view')?scoped(c).length:0);}const examScopeIds=new Set(scoped('exams').map(x=>x.examinationId).filter(Boolean));const parentExams=Object.entries(data.examinations||{}).map(([id,v])=>({id,...v})).filter(x=>x.status!=='archived').filter(x=>owner||x.createdBy===req.user.uid||examScopeIds.has(x.id));stats.exams=(owner||can(req.user,'examinations','view'))?parentExams.length:0;stats.examPapers=(owner||can(req.user,'examinations','view'))?scoped('exams').length:0;stats.admissions=owner?Object.values(data.admissions||{}).filter(x=>x.status==='pending').length:0;stats.pendingTeacherRequests=owner?Object.values(data.teacherJoinRequests||{}).filter(x=>x.status==='pending').length:0;const recentAdmissions=owner?Object.entries(data.admissions||{}).map(([id,v])=>({id,...v})).sort((a,b)=>(b.createdAt||0)-(a.createdAt||0)).slice(0,5):[];const paperCountBy={};for(const e of Object.values(data.exams||{}))if(e?.examinationId&&e.status!=='archived')paperCountBy[e.examinationId]=(paperCountBy[e.examinationId]||0)+1;const recentExams=can(req.user,'examinations','view')?parentExams.sort((a,b)=>(b.createdAt||0)-(a.createdAt||0)).slice(0,5).map(x=>({id:x.id,name:x.name,status:x.status,paperCount:paperCountBy[x.id]||0,subjectName:`${paperCountBy[x.id]||0} paper${(paperCountBy[x.id]||0)===1?'':'s'}`,createdAt:x.createdAt})):[];const recentTeacherRequests=owner?Object.entries(data.teacherJoinRequests||{}).map(([id,v])=>({id,...v})).filter(x=>x.status==='pending').slice(0,5):[];const allActivities=Object.entries(data.auditLogs||{}).map(([id,v])=>({id,...v})).sort((a,b)=>(b.at||0)-(a.at||0));let recentActivities=[];if(can(req.user,'auditLogs','view')){if(owner){recentActivities=allActivities.slice(0,8);}else{const candidates=allActivities.slice(0,40);const scopedActivities=await Promise.all(candidates.map(async item=>{const kind=String(item.action||'').split('.')[0],related=kind&&item.recordId?await db.get(`institutes/${iid}/${kind}/${item.recordId}`):null;return related&&inTeacherScope(req.user,related,kind)?item:null;}));recentActivities=scopedActivities.filter(Boolean).slice(0,8);}}res.json({institute:data.profile,stats,recentAdmissions,recentExams,recentTeacherRequests,recentActivities,assignedAcademicScope:req.user.academicScope||{}});}catch(e){next(e);}});
function scope(req,res,next){const id=req.user.instituteId;if(!id)return res.status(403).json({message:'Join an institute before accessing institute resources.'});req.instituteId=id;next();}

