 const fieldModules={departmentId:'departments',courseId:'courses',semesterId:'semesters',classId:'classes',sectionId:'sections',batchId:'batches',academicYearId:'academicYears'};const requiredFields={};for(const [entity,allowedFieldsForEntity] of Object.entries(allowedFields)){requiredFields[entity]=[...new Set((input.requiredFields?.[entity]||[]).filter(x=>allowedFieldsForEntity.includes(x)&&modules[fieldModules[x]]?.enabled))];}
