r.post('/admissions/request',requireAuth,async(req,res,next)=>{try{if(req.user.role!=='student')return res.status(403).json({message:'Only student accounts can request admission.'});if(req.user.instituteId)return res.status(409).json({message:'You are already linked to an institute.'});const code=String(req.body.code||'').trim().toUpperCase(),instituteId=await db.get(`instituteLookups/${code}`);if(!instituteId)return res.status(404).json({message:'Institute code not found.'});const institute=await db.get(`institutes/${instituteId}/profile`);if(!institute||institute.status!=='active')return res.status(404).json({message:'Institute is unavailable.'});const duplicate=await db.get(`institutes/${instituteId}/admissionByStudent/${req.user.uid}`);if(duplicate)return res.status(409).json({message:'An admission request already exists.'});const id=db.key(),now=Date.now(),record={id,studentUid:req.user.uid,studentName:req.user.name,mobile:req.user.mobile,status:'pending',createdAt:now};await db.update({[`institutes/${instituteId}/admissions/${id}`]:record,[`institutes/${instituteId}/admissionByStudent/${req.user.uid}`]:id,[`users/${req.user.uid}/admissionStatus`]:'pending',[`users/${req.user.uid}/requestedInstituteId`]:instituteId});res.status(201).json({request:record,institute:{name:institute.name,code}});}catch(e){next(e);}});
r.post('/admissions/:id/decision',requireAuth,allow('institute_owner','institute_admin'),async(req,res,next)=>{let studentId=null;try{const id=req.params.id,base=`institutes/${req.user.instituteId}/admissions/${id}`,a=await db.get(base);if(!a)return res.status(404).json({message:'Admission request not found.'});const status=req.body.status;if(!['approved','rejected'].includes(status))return res.status(400).json({message:'Choose approve or reject.'});const now=Date.now();if(status==='approved')studentId=await claimStudentId(req.user.instituteId,a.studentUid);const attendanceQrToken=status==='approved'?crypto.randomBytes(24).toString('base64url'):null;await db.update({[`${base}/status`]:status,[`${base}/reviewedAt`]:now,[`${base}/reviewedBy`]:req.user.uid,[`${base}/note`]:String(req.body.note||'').slice(0,500),[`users/${a.studentUid}/admissionStatus`]:status,...(status==='approved'?{[`users/${a.studentUid}/instituteId`]:req.user.instituteId,[`users/${a.studentUid}/admissionId`]:id,[`institutes/${req.user.instituteId}/students/${a.studentUid}`]:{uid:a.studentUid,linkedUid:a.studentUid,studentId,name:a.studentName,mobile:a.mobile,status:'active',admissionStatus:'approved',attendanceQrToken,createdAt:a.createdAt},[`institutes/${req.user.instituteId}/studentQrMappings/${attendanceQrToken}`]:{recordId:a.studentUid,studentId,status:'active',createdAt:now},[`studentIdLookups/${studentId}`]:{instituteId:req.user.instituteId,recordId:a.studentUid}}:{})});res.json({ok:true,studentId:status==='approved'?studentId:undefined});}catch(e){if(studentId)await db.remove(`studentIdLookups/${studentId}`).catch(()=>{});next(e);}});
